from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.snapshot_collection.classical_snapshot_collection.snapshot_collection_prototype import SnapshotCollection


class SnapshotCollectionFactory(OperationFactoryPrototype):
    def __init__(self):
        super(SnapshotCollectionFactory, self).__init__()

    def get_kpi(self, coverage="full"):
        """
        Gets kpi for snapshot collection operation.
        :param coverage: coverage type for snapshot, full or minor
        :type coverage: str
        :return: dictionary with timeout, requirement and operation description for snapshot collection
        :rtype: dict
        """
        return SnapshotCollection(self.bts).get_kpi(coverage=coverage)
